17 | package com.ibm.jp.automation.e2m.eclipse;
18 | 
19 | import org.w3c.dom.Document;
20 | import org.w3c.dom.Element;
21 | import org.w3c.dom.NodeList;
22 | 
23 | import com.ibm.jp.automation.e2m.maven.DependencyResolver;
24 | import com.ibm.jp.automation.e2m.spec.JavaVersion;
25 | 
26 | import javax.xml.parsers.DocumentBuilder;
27 | import javax.xml.parsers.DocumentBuilderFactory;
28 | import java.io.IOException;
29 | import java.nio.file.Files;
30 | import java.nio.file.Path;
31 | import java.util.ArrayList;
32 | import java.util.List;
33 | import java.util.Properties;
34 | 
35 | /**
36 |  * Eclipseプロジェクトのメタデータファイルを解析して {@link EclipseProject} を返すパーサー。
37 |  */
38 | public class EclipseProjectParser {
39 | 
40 |     private static final String WTP_NATURE = "org.eclipse.wst.common.project.facet.core.nature";
41 |     private static final String DEFAULT_JAVA_VERSION = "11";
42 | 
43 |     /**
44 |      * 指定した入力ディレクトリを解析して {@link EclipseProject} を返す。
45 |      *
46 |      * @param inputDir Eclipseプロジェクトのルートディレクトリ
47 |      * @return 解析結果
48 |      * @throws Exception 解析中に発生した例外
49 |      */
50 |     public static EclipseProject parse(Path inputDir) throws Exception {
51 |         DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
52 |         DocumentBuilder builder = factory.newDocumentBuilder();
53 | 
54 |         // ── .project ──────────────────────────────────────────────
55 |         Path projectFile = inputDir.resolve(".project");
56 |         // 行頭の空白・改行をスキップするため InputStream 経由でパース
57 |         Document projectDoc = builder.parse(
58 |                 new java.io.ByteArrayInputStream(
59 |                         Files.readString(projectFile).stripLeading().getBytes(java.nio.charset.StandardCharsets.UTF_8)));
60 |         projectDoc.getDocumentElement().normalize();
61 | 
62 |         String projectName = projectDoc.getElementsByTagName("name")
63 |                 .item(0).getTextContent().trim();
64 | 
65 |         boolean webProject = false;
66 |         NodeList natures = projectDoc.getElementsByTagName("nature");
67 |         for (int i = 0; i < natures.getLength(); i++) {
68 |             if (WTP_NATURE.equals(natures.item(i).getTextContent().trim())) {
69 |                 webProject = true;
70 |                 break;
71 |             }
72 |         }
73 | 
74 |         // ── .classpath ────────────────────────────────────────────
75 |         Path classpathFile = inputDir.resolve(".classpath");
76 |         Document cpDoc = builder.parse(classpathFile.toFile());
77 |         cpDoc.getDocumentElement().normalize();
78 | 
79 |         List<String> sourceFolders = new ArrayList<>();
80 |         List<ClasspathEntry> libEntries = new ArrayList<>();
81 |         String outputFolder = null;
82 | 
83 |         NodeList entries = cpDoc.getElementsByTagName("classpathentry");
84 |         for (int i = 0; i < entries.getLength(); i++) {
85 |             Element entry = (Element) entries.item(i);
86 |             String kind = entry.getAttribute("kind");
87 |             String path = entry.getAttribute("path");
88 | 
89 |             switch (kind) {
90 |                 case "src" -> {
91 |                     if (!isOptional(entry)) {
92 |                         sourceFolders.add(path);
93 |                     }
94 |                 }
95 |                 case "output" -> outputFolder = path;
96 |                 case "lib" -> {
97 |                     boolean exported = "true".equals(entry.getAttribute("exported"));
98 |                     boolean test = hasAttribute(entry, "test", "true");
99 |                     libEntries.add(new ClasspathEntry(kind, path, exported, test));
100 |                 }
101 |                 case "con" -> {
102 |                     if ("org.eclipse.jst.j2ee.internal.web.container".equals(path)) {
103 |                         libEntries.add(new ClasspathEntry(kind, path, false, false));
104 |                     }
105 |                 }
106 |             }
107 |         }
108 | 
109 |         // ── .settings/org.eclipse.jdt.core.prefs ─────────────────
110 |         // source/target を prefs から取得し、見つからない場合は .classpath の con エントリの値を使う
111 |         String[] versions = parseJdtCorePrefs(inputDir);
112 |         JavaVersion javaSourceVersion = JavaVersion.of(versions[0]);
113 |         JavaVersion javaTargetVersion = JavaVersion.of(versions[1]);
114 | 
115 |         // ── WTP: .settings/org.eclipse.wst.common.component ──────
116 |         String webContentRoot = null;
117 |         String webVersion = null;
118 |         if (webProject) {
119 |             webContentRoot = parseWebContentRoot(inputDir, builder);
120 |             webVersion = parseWebVersion(inputDir, builder);
121 |         }
122 | 
123 |         // ── ClasspathEntry リスト → JarFile リスト ─────────────────
124 |         List<JarFile> jarFiles = buildJarFiles(libEntries, webContentRoot, inputDir);
125 | 
126 |         return new EclipseProject(
127 |                 projectName,
128 |                 webProject,
129 |                 List.copyOf(sourceFolders),
130 |                 outputFolder,
131 |                 List.copyOf(jarFiles),
132 |                 webContentRoot,
133 |                 javaSourceVersion,
134 |                 javaTargetVersion,
135 |                 webVersion
136 |         );
137 |     }
138 | 
139 |     /**
140 |      * `.settings/org.eclipse.jdt.core.prefs` を解析して [sourceVersion, targetVersion] を返す。
141 |      * ファイルが存在しない、またはキーが見つからない場合は fallback 値を使用する。
142 |      */
143 |     private static String[] parseJdtCorePrefs(Path inputDir) {
144 |         Path prefsFile = inputDir.resolve(".settings")
145 |                 .resolve("org.eclipse.jdt.core.prefs");
146 | 
147 |         if (Files.exists(prefsFile)) {
148 |             Properties props = new Properties();
149 |             try (var reader = Files.newBufferedReader(prefsFile)) {
150 |                 props.load(reader);
151 |                 String source = normalizeJavaVersion(
152 |                         props.getProperty("org.eclipse.jdt.core.compiler.source"));
153 |                 String target = normalizeJavaVersion(
154 |                         props.getProperty("org.eclipse.jdt.core.compiler.codegen.targetPlatform"));
155 |                 // 両方取得できた場合はそのまま使う。片方のみの場合はもう一方も同じ値にする
156 |                 if (source != null && target != null) {
157 |                     return new String[]{source, target};
158 |                 } else if (source != null) {
159 |                     return new String[]{source, source};
160 |                 } else if (target != null) {
161 |                     return new String[]{target, target};
162 |                 }
163 |             } catch (IOException e) {
164 |                 // 読み込み失敗時は fallback を使用
165 |             }
166 |         }
167 | 
168 |         return new String[]{DEFAULT_JAVA_VERSION, DEFAULT_JAVA_VERSION};
169 |     }
170 | 
171 |     /**
172 |      * "1.8" → "1.8"、"17" → "17" のようにそのまま返す。
173 |      * null や空文字の場合は null を返す。
174 |      */
175 |     private static String normalizeJavaVersion(String value) {
176 |         if (value == null || value.isBlank()) {
177 |             return null;
178 |         }
179 |         return value.trim();
180 |     }
181 | 
182 |     /**
183 |      * `.settings/org.eclipse.wst.common.component` を解析して Webコンテンツルートを返す。
184 |      * ファイルが存在しない場合は null を返す。
185 |      * 先頭の "/" は除去した相対パスとして返す。
186 |      */
187 |     private static String parseWebContentRoot(Path inputDir, DocumentBuilder builder) {
188 |         Path componentFile = inputDir.resolve(".settings")
189 |                 .resolve("org.eclipse.wst.common.component");
190 | 
191 |         if (!Files.exists(componentFile)) {
192 |             return null;
193 |         }
194 | 
195 |         try {
196 |             Document doc = builder.parse(componentFile.toFile());
197 |             doc.getDocumentElement().normalize();
198 | 
199 |             NodeList resources = doc.getElementsByTagName("wb-resource");
200 |             for (int i = 0; i < resources.getLength(); i++) {
201 |                 Element res = (Element) resources.item(i);
202 |                 if ("defaultRootSource".equals(res.getAttribute("tag"))) {
203 |                     String sourcePath = res.getAttribute("source-path");
204 |                     // 先頭の "/" を除去して相対パスに正規化
205 |                     if (sourcePath.startsWith("/")) {
206 |                         sourcePath = sourcePath.substring(1);
207 |                     }
208 |                     return sourcePath;
209 |                 }
210 |             }
211 |         } catch (Exception e) {
212 |             // ファイルが壊れている場合は null を返す
213 |         }
214 | 
215 |         return null;
216 |     }
217 | 
218 |     /**
219 |      * {@code ClasspathEntry} のリストから {@link JarFile} のリストを構築する。
220 |      *
221 |      * <ul>
222 |      *   <li>{@code path} が {@code .jar} で終わるエントリ: {@code test} 属性・{@code exported}
223 |      *       属性をそのまま {@link JarFile} に引き継ぐ。スコープの決定は
224 |      *       {@link DependencyResolver} 内で行う。</li>
225 |      *   <li>{@code path} が {@code org.eclipse.jst.j2ee.internal.web.container} のエントリ:
226 |      *       {@code webContentRoot} が非 null の場合、対応する {@code WEB-INF/lib} ディレクトリを
227 |      *       走査して各 {@code .jar} ファイルを {@code exported=true} として追加する。</li>
228 |      *   <li>それ以外は無視する。</li>
229 |      * </ul>
230 |      *
231 |      * @param libEntries     {@code .classpath} パースで収集した {@link ClasspathEntry} のリスト
232 |      * @param webContentRoot Webコンテンツルートの相対パス（null の場合は web container エントリを無視）
233 |      * @param inputDir       Eclipseプロジェクトのルートディレクトリ
234 |      * @return 構築した {@link JarFile} のリスト
235 |      */
236 |     private static List<JarFile> buildJarFiles(List<ClasspathEntry> libEntries,
237 |                                                String webContentRoot, Path inputDir) {
238 |         List<JarFile> jarFiles = new ArrayList<>();
239 |         for (ClasspathEntry e : libEntries) {
240 |             if (e.path().endsWith(".jar")) {
241 |                 jarFiles.add(new JarFile(e.path(), e.test(), e.exported()));
242 |             } else if ("org.eclipse.jst.j2ee.internal.web.container".equals(e.path())
243 |                     && webContentRoot != null) {
244 |                 Path webInfLib = inputDir.resolve(webContentRoot).resolve("WEB-INF/lib");
245 |                 if (Files.isDirectory(webInfLib)) {
246 |                     try (var stream = Files.list(webInfLib)) {
247 |                         // WEB-INF/lib 配下のJARはコンテナが提供するものではなくWARに同梱されるため
248 |                         // exported=true として扱う
249 |                         stream.filter(p -> p.getFileName().toString().endsWith(".jar"))
250 |                               .sorted()
251 |                               .forEach(p -> jarFiles.add(
252 |                                       new JarFile(inputDir.relativize(p).toString(), false, true)));
253 |                     } catch (IOException ex) {
254 |                         // 読み取り失敗時は無視
255 |                     }
256 |                 }
257 |             }
258 |             // それ以外は無視
259 |         }
260 |         return jarFiles;
261 |     }
262 | 
263 |     /**
264 |      * {@code classpathentry} 要素の {@code <attributes>} 子要素内に、
265 |      * 指定した名前と値を持つ {@code <attribute>} 要素が存在するかどうかを返す。
266 |      *
267 |      * @param entry 検査する {@code classpathentry} 要素
268 |      * @param name  属性名
269 |      * @param value 属性値
270 |      * @return 存在する場合は {@code true}
271 |      */
272 |     private static boolean hasAttribute(Element entry, String name, String value) {
273 |         NodeList attributesList = entry.getElementsByTagName("attributes");
274 |         if (attributesList.getLength() == 0) {
275 |             return false;
276 |         }
277 |         NodeList attributes = ((Element) attributesList.item(0)).getElementsByTagName("attribute");
278 |         for (int i = 0; i < attributes.getLength(); i++) {
279 |             Element attr = (Element) attributes.item(i);
280 |             if (name.equals(attr.getAttribute("name"))
281 |                     && value.equals(attr.getAttribute("value"))) {
282 |                 return true;
283 |             }
284 |         }
285 |         return false;
286 |     }
287 | 
288 |     /**
289 |      * {@code classpathentry} 要素が optional かどうかを返す。
290 |      * {@code <attributes>} 子要素内に {@code <attribute name="optional" value="true"/>} が
291 |      * 存在する場合に {@code true} を返す。
292 |      */
293 |     private static boolean isOptional(Element entry) {
294 |         return hasAttribute(entry, "optional", "true");
295 |     }
296 | 
297 |     /**
298 |      * `.settings/org.eclipse.wst.common.project.facet.core.xml` を解析して
299 |      * {@code jst.web} ファセットの version を返す。
300 |      * ファイルが存在しない、またはファセットが見つからない場合は null を返す。
301 |      */
302 |     private static String parseWebVersion(Path inputDir, DocumentBuilder builder) {
303 |         Path facetFile = inputDir.resolve(".settings")
304 |                 .resolve("org.eclipse.wst.common.project.facet.core.xml");
305 | 
306 |         if (!Files.exists(facetFile)) {
307 |             return null;
308 |         }
309 | 
310 |         try {
311 |             Document doc = builder.parse(facetFile.toFile());
312 |             doc.getDocumentElement().normalize();
313 | 
314 |             NodeList installed = doc.getElementsByTagName("installed");
315 |             for (int i = 0; i < installed.getLength(); i++) {
316 |                 Element el = (Element) installed.item(i);
317 |                 if ("jst.web".equals(el.getAttribute("facet"))) {
318 |                     return el.getAttribute("version");
319 |                 }
320 |             }
321 |         } catch (Exception e) {
322 |             // ファイルが壊れている場合は null を返す
323 |         }
324 | 
325 |         return null;
326 |     }
327 | }
