49 | @Command(name = "e2m", description = "Eclipse project to Maven project converter", version = "1.0.1", mixinStandardHelpOptions = true)
50 | public class Main implements Callable<Integer> {
51 | 
52 |     private static final Logger log = AppLogger.get(Main.class);
53 |     private static String e2mVersion;
54 | 
55 |     /** コマンドライン引数のコピー（デバッグ ZIP 用）。 */
56 |     private String[] rawArgs;
57 | 
58 |     @Option(names = {"-g", "--groupId"}, required = false, description = "Maven groupId of the output project")
59 |     private String groupId;
60 | 
61 |     @Option(names = {"-a", "--artifactId"}, required = false, description = "Maven artifactId of the output project")
62 |     private String artifactId;
63 | 
64 |     @Option(names = {"-v", "--artifactVersion"}, required = false, description = "Maven version of the output project (default: 1.0-SNAPSHOT)")
65 |     private String artifactVersion;
66 |     private static final String DEFAULT_ARTIFACT_VERSION = "1.0-SNAPSHOT";
67 | 
68 |     @Option(names = {"--javaTargetVersion"}, required = false, converter = JavaVersionConverter.class,
69 |             description = "Override maven.compiler.target in the generated pom.xml (default: taken from the Eclipse project settings)")
70 |     private JavaVersion javaTargetVersion;
71 | 
72 |     @Option(names = {"--convertToUtf8"}, description = "Convert source files to UTF-8 encoding during copy")
73 |     private boolean convertToUtf8;
74 | 
75 |     @Option(names = {"-e", "--sourceEncoding"}, required = false, description = "Source encoding of the input files (e.g. Shift_JIS). Required when --convertToUtf8 is specified.")
76 |     private String sourceEncoding;
77 | 
78 |     @Option(names = {"--debug"}, description = "Output debug information as e2m_debug_<datetime>.zip in the output directory")
79 |     private boolean debug;
80 | 
81 |     @Parameters(index = "0", paramLabel = "<inputDir>", description = "Eclipse project directory to convert")
82 |     private File inputDir;
83 | 
84 |     @Parameters(index = "1", paramLabel = "<outputDir>", description = "Output directory for the Maven project")
85 |     private File outputDir;
86 | 
87 |     public static void main(String[] args) {
88 |         AppLogger.init();
89 |         Main main = new Main();
90 |         main.rawArgs = args.clone();
91 |         CommandLine command = new CommandLine(main);
92 |         e2mVersion = command.getCommandSpec().version()[0];
93 |         System.exit(command.execute(args));
94 |     }
