96 |     @Override
97 |     public Integer call() {
98 |         // --debug が指定された場合はファイルログを有効化（outputDir 配下に一時ファイルを作成）
99 |         if (debug) {
100 |             String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
101 |             Path logFilePath = outputDir.toPath().resolve("e2m_debug_" + timestamp + ".log");
102 |             AppLogger.enableDebug(logFilePath);
103 |             log.debug("デバッグモード有効: ログファイル={}", logFilePath);
104 |             log.debug("e2mバージョン={}", e2mVersion);
105 |         }
106 | 
107 |         Path eclipsePath = inputDir.toPath();
108 |         Path mavenPath = null; 
109 | 
110 |         // 1. 引数の確認
111 |         if (!inputDir.isDirectory()) {
112 |             log.error(Messages.get("main.inputDirNotFound", inputDir));
113 |             return 1;
114 |         }
115 |         if (!eclipsePath.resolve(".project").toFile().exists()) {
116 |             log.error(Messages.get("main.notEclipseProject", inputDir));
117 |             return 1;
118 |         }
119 |         if (outputDir.exists() && !outputDir.isDirectory()) {
120 |             log.error(Messages.get("main.outputPathMustBeDirectory", outputDir));
121 |             return 1;
122 |         }
123 |         if (javaTargetVersion != null && javaTargetVersion.isUnknown()) {
124 |             log.error(Messages.get("main.invalidJavaTargetVersion", javaTargetVersion));
125 |             return 1;
126 |         }
127 | 
128 |         try {
129 |             // 2. Eclipseプロジェクト情報をパース
130 |             log.info("");
131 |             log.info(Messages.get("main.step1"));
132 |             EclipseProject eclipseProject = EclipseProjectParser.parse(eclipsePath);
133 |             log.info(Messages.get("main.projectName", eclipseProject.projectName()));
134 |             log.info(Messages.get("main.projectType",
135 |                     eclipseProject.webProject() ? Messages.get("main.projectType.web") : Messages.get("main.projectType.java")));
136 |             log.info(Messages.get("main.javaSourceVersion", eclipseProject.javaSourceVersion()));
137 |             log.info(Messages.get("main.javaTargetVersion", eclipseProject.javaTargetVersion()));
138 |             if (eclipseProject.webProject()) {
139 |                 log.info(Messages.get("main.webVersion", eclipseProject.webVersion()));
140 |             }
141 |             log.info(Messages.get("main.sourceFolders", eclipseProject.sourceFolders()));
142 |             if (eclipseProject.webProject()) {
143 |                 log.info(Messages.get("main.webContentFolder", eclipseProject.webContentRoot()));
144 |             }
145 |             log.info(Messages.get("main.jarCount", eclipseProject.jarFiles().size()));
146 | 
147 |             if (eclipseProject.javaSourceVersion().isUnknown()) {
148 |                 log.error(Messages.get("main.unrecognizedJavaSourceVersion", eclipseProject.javaSourceVersion()));
149 |                 return 1;
150 |             }
151 | 
152 |             log.info("");
153 |             log.info(Messages.get("main.step2"));
154 |             String defaultArtifactId = convertToArtifactId(eclipseProject.projectName());
155 |             if (groupId == null || groupId.isBlank()) {
156 |                 // オプション未指定の場合は対話的に入力を受け付ける
157 |                 try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
158 |                     log.debug("対話的入力モード開始");
159 |                     groupId = promptIfAbsent(reader, "groupId", groupId, null);
160 |                     artifactId = promptIfAbsent(reader, "artifactId", artifactId, defaultArtifactId);
161 |                     artifactVersion = promptIfAbsent(reader, "artifactVersion", artifactVersion, DEFAULT_ARTIFACT_VERSION);
162 |                     log.debug("groupId: {}", groupId);
163 |                     log.debug("artifactId: {}", artifactId);
164 |                     log.debug("version: {}", artifactVersion);
165 |                     // --convertToUtf8 指定時は sourceEncoding も対話入力
166 |                     if (convertToUtf8) {
167 |                         sourceEncoding = promptIfAbsent(reader, "sourceEncoding", sourceEncoding, null);
168 |                     }
169 |                     log.debug("sourceEncoding: {}", sourceEncoding);
170 |                 }
171 |             } else {
172 |                 // 少なくとも--groupIdが指定されていれば，あとは空ならデフォルトを使用する
173 |                 if (artifactId == null || artifactId.isBlank()) {
174 |                     artifactId = defaultArtifactId;
175 |                 }
176 |                 if (artifactVersion == null || artifactId.isBlank()) {
177 |                     artifactVersion = DEFAULT_ARTIFACT_VERSION;
178 |                 }
179 |                 log.info(Messages.get("main.groupId", groupId));
180 |                 log.info(Messages.get("main.artifactId", artifactId));
181 |                 log.info(Messages.get("main.version", artifactVersion));
182 |                 // --convertToUtf8 指定時は sourceEncoding も対話入力（--groupId 指定時で未指定の場合）
183 |                 if (convertToUtf8 && (sourceEncoding == null || sourceEncoding.isBlank())) {
184 |                     log.debug("対話的入力モード開始");
185 |                     try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
186 |                         sourceEncoding = promptIfAbsent(reader, "sourceEncoding", sourceEncoding, null);
187 |                     }
188 |                     log.debug("sourceEncoding: {}", sourceEncoding);
189 |                 }
190 |             }
191 | 
192 |             // --convertToUtf8 指定時の sourceEncoding バリデーション
193 |             Charset srcCharset = null;
194 |             if (convertToUtf8) {
195 |                 try {
196 |                     srcCharset = Charset.forName(sourceEncoding);
197 |                 } catch (Exception e) {
198 |                     log.error(Messages.get("main.invalidSourceEncoding", sourceEncoding));
199 |                     return 1;
200 |                 }
201 |             }
202 | 
203 |             // 出力先は outputDir/artifactId
204 |             mavenPath = outputDir.toPath().resolve(artifactId);
205 |             if (mavenPath.toFile().exists()) {
206 |                 log.error(Messages.get("main.outputDirAlreadyExists", mavenPath));
207 |                 return 1;
208 |             }
209 | 
210 |             log.info("");
211 |             log.info(Messages.get("main.conversionStart"));
212 |             log.info(Messages.get("main.input", eclipsePath.toAbsolutePath()));
213 |             log.info(Messages.get("main.output", mavenPath.toAbsolutePath()));
214 | 
215 |             // 3.(続き) JAR依存関係を解決
216 |             log.info("");
217 |             log.info(Messages.get("main.step3"));
218 |             List<MavenDependency> dependencies = DependencyResolver.resolve(eclipseProject.jarFiles(), eclipsePath);
219 |             long found = dependencies.stream().filter(d -> !"system".equals(d.scope())).count();
220 |             long system = dependencies.stream().filter(d -> "system".equals(d.scope())).count();
221 |             log.info(Messages.get("main.foundDependencies", found));
222 |             log.info(Messages.get("main.systemDependencies", system));
223 | 
224 |             // 4. pom.xml を生成
225 |             log.info("");
226 |             log.info(Messages.get("main.step4"));
227 |             // --javaTargetVersion が指定された場合はソースバージョンと比較してバリデーション
228 |             JavaVersion sourceVer = eclipseProject.javaSourceVersion();
229 |             if (javaTargetVersion != null) {
230 |                 if (!sourceVer.isUnknown() && javaTargetVersion.compareTo(sourceVer) < 0) {
231 |                     log.error(Messages.get("main.javaTargetLowerThanSource",
232 |                             javaTargetVersion, eclipseProject.javaSourceVersion()));
233 |                     return 1;
234 |                 }
235 |             }
236 |             // 実効 javaTargetVersion を確定（--javaTargetVersion 指定 > Eclipseプロジェクト設定）
237 |             JavaVersion effectiveTargetVersion = (javaTargetVersion != null && !javaTargetVersion.isUnknown())
238 |                     ? javaTargetVersion
239 |                     : eclipseProject.javaTargetVersion();
240 |             PomGenerator.generate(eclipseProject, dependencies, groupId, artifactId, artifactVersion,
241 |                     effectiveTargetVersion, convertToUtf8, mavenPath);
242 | 
243 |             // 5. ソース・Webコンテンツをコピー
244 |             log.info("");
245 |             log.info(Messages.get("main.step5"));
246 |             if (convertToUtf8) {
247 |                 log.info(Messages.get("main.encodingConversionMode", sourceEncoding));
248 |             }
249 |             ProjectCopier.copy(eclipseProject, dependencies, eclipsePath, mavenPath,
250 |                     convertToUtf8, srcCharset, effectiveTargetVersion);
251 | 
252 |             log.info("");
253 |             log.info(Messages.get("main.conversionComplete"));
254 |             log.info(Messages.get("main.outputDir", mavenPath.toAbsolutePath()));
255 | 
256 |             return 0;
257 | 
258 |         } catch (Exception e) {
259 |             log.error(Messages.get("main.conversionError", e.getMessage()));
260 |             log.debug("スタックトレース:", e);
261 |             return 2;
262 |         } finally {
263 |             // --debug オプション: デバッグ ZIP を生成
264 |             if (debug) try {
265 |                 DebugArchiver.archive(eclipsePath, outputDir.toPath(), mavenPath, rawArgs);
266 |             } catch (IOException e) {
267 |                 e.printStackTrace();
268 |             }
269 |         }
270 |     }
271 | 
272 |     /**
273 |      * 引数が null または空の場合にプロンプトを表示して入力を受け付ける。
274 |      * デフォルト値がある場合は "[default]" 形式で表示し、空入力でデフォルト値を採用する。
275 |      *
276 |      * @param reader       入力ストリーム
277 |      * @param name         項目名（表示用）
278 |      * @param value        コマンドライン引数の値（null または空の場合にプロンプト表示）
279 |      * @param defaultValue デフォルト値（null の場合はデフォルトなし）
280 |      * @return 確定した値
281 |      */
282 |     private static String promptIfAbsent(BufferedReader reader, String name,
283 |             String value, String defaultValue) throws Exception {
284 |         if (value != null && !value.isBlank()) {
285 |             return value;
286 |         }
287 |         while (true) {
288 |             if (defaultValue != null) {
289 |                 System.out.print(Messages.get("main.prompt.withDefault", name, defaultValue));
290 |             } else {
291 |                 System.out.print(Messages.get("main.prompt.withoutDefault", name));
292 |             }
293 |             System.out.flush();
294 |             String line = reader.readLine();
295 |             if (line == null) {
296 |                 // EOF（パイプ等）の場合はデフォルト値を使用
297 |                 return defaultValue != null ? defaultValue : "";
298 |             }
299 |             String trimmed = line.trim();
300 |             if (trimmed.isEmpty()) {
301 |                 if (defaultValue != null) {
302 |                     return defaultValue;
303 |                 }
304 |                 // 対話的入力モードでのメッセージは，ロガーを使わず，直接System.outに出力
305 |                 System.out.print(Messages.get("main.prompt.enterValue"));
306 |                 continue;
307 |             }
308 |             return trimmed;
309 |         }
310 |     }
311 | 
312 |     // artifactIdとして許可する文字（半角英数字、ハイフン、アンダースコア）以外にマッチする正規表現
313 |     private static final Pattern INVALID_CHARS = Pattern.compile("[^a-z0-9\\-_]");
314 | 
315 |     // キャメルケースの境界（大文字の前）にマッチする正規表現
316 |     private static final Pattern CAMEL_CASE_BOUNDARY = Pattern.compile("(?<=[a-z0-9])(?=[A-Z])");
317 | 
318 |     /**
319 |      * プロジェクト名からMavenのartifactIdとして利用可能な文字列を生成します。
320 |      *
321 |      * @param projectName プロジェクト名
322 |      * @return artifactId用文字列
323 |      */
324 |     public static String convertToArtifactId(String projectName) {
325 |         if (projectName == null || projectName.isBlank()) {
326 |             return "default-artifact";
327 |         }
328 | 
329 |         // 1. パッケージ名が含まれている場合（完全限定名）、最後のクラス名部分だけを抽出
330 |         String simpleName = projectName.substring(projectName.lastIndexOf('.') + 1);
331 | 
332 |         // 2. キャメルケース（OrderManager -> Order-Manager）をハイフン区切りに変換
333 |         String kebabCase = CAMEL_CASE_BOUNDARY.matcher(simpleName).replaceAll("-");
334 | 
335 |         // 3. すべて小文字に変換
336 |         String lowerCase = kebabCase.toLowerCase();
337 | 
338 |         // 4. artifactIdとして使えない文字（日本語や特殊記号など）を完全に除去
339 |         String sanitized = INVALID_CHARS.matcher(lowerCase).replaceAll("");
340 | 
341 |         // 5. 連続したハイフンやアンダースコアを綺麗に整理
342 |         sanitized = sanitized.replaceAll("[-_]{2,}", "-");
343 | 
344 |         // 6. 先頭や末尾にあるハイフン・アンダースコアを除去
345 |         sanitized = sanitized.replaceAll("^[-_]+|[-_]+$", "");
346 | 
347 |         // すべての文字が削られて空になった場合のフォールバック
348 |         return sanitized.isBlank() ? "converted-artifact" : sanitized;
349 |     }
350 | 
351 |     /**
352 |      * picocli 用の {@link JavaVersion} 型変換クラス。
353 |      * 変換に失敗した場合は {@link JavaVersion#UNKNOWN_VERSION} を返す。
354 |      */
355 |     static class JavaVersionConverter implements ITypeConverter<JavaVersion> {
356 |         @Override
357 |         public JavaVersion convert(String value) {
358 |             return JavaVersion.of(value);
359 |         }
360 |     }
361 | }
