40 | /**
41 |  * EclipseProject情報と依存関係リストからMavenのpom.xmlを生成するクラス。
42 |  */
43 | public class PomGenerator {
44 | 
45 |     private static final Logger log = AppLogger.get(PomGenerator.class);
46 | 
47 |     private static final String MAVEN_COMPILER_PLUGIN_VERSION = "3.15.0";
48 |     private static final String MAVEN_WAR_PLUGIN_VERSION = "3.5.1";
49 |     private static final String NATIVE2ASCII_PLUGIN_VERSION = "2.1.1";
50 | 
51 |     private PomGenerator() {}
52 | 
53 |     /**
54 |      * pom.xmlを生成して出力ディレクトリに保存する。
55 |      *
56 |      * @param eclipseProject        パース済みEclipseプロジェクト情報
57 |      * @param dependencies          解決済み依存関係リスト
58 |      * @param groupId               生成するpom.xmlのgroupId
59 |      * @param artifactId            生成するpom.xmlのartifactId
60 |      * @param version               生成するpom.xmlのversion
61 |      * @param effectiveTargetVersion maven.compiler.targetに使用するJavaバージョン。
62 |      * @param convertToUtf8      --convert-to-utf8 オプションが指定されているか
63 |      * @param outputDir          出力ディレクトリ
64 |      * @throws Exception XML生成またはファイル書き込みに失敗した場合
65 |      */
66 |     public static void generate(
67 |             EclipseProject eclipseProject,
68 |             List<MavenDependency> dependencies,
69 |             String groupId,
70 |             String artifactId,
71 |             String version,
72 |             JavaVersion effectiveTargetVersion,
73 |             boolean convertToUtf8,
74 |             Path outputDir) throws Exception {
75 | 
76 |         log.debug("  generate開始");
77 |         DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
78 |         DocumentBuilder db = dbf.newDocumentBuilder();
79 |         Document doc = db.newDocument();
80 | 
81 |         // <project>
82 |         Element project = doc.createElement("project");
83 |         project.setAttribute("xmlns", "http://maven.apache.org/POM/4.0.0");
84 |         project.setAttribute("xmlns:xsi", "http://www.w3.org/2001/XMLSchema-instance");
85 |         project.setAttribute("xsi:schemaLocation",
86 |                 "http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd");
87 |         doc.appendChild(project);
88 | 
89 |         addTextElement(doc, project, "modelVersion", "4.0.0");
90 |         addTextElement(doc, project, "groupId", groupId);
91 |         addTextElement(doc, project, "artifactId", artifactId);
92 |         addTextElement(doc, project, "version", version);
93 | 
94 |         if (eclipseProject.webProject()) {
95 |             log.debug("  packaging: war");
96 |             addTextElement(doc, project, "packaging", "war");
97 |         }
98 | 
99 |         // <properties>
100 |         JavaVersion javaSourceVersion = eclipseProject.javaSourceVersion();
101 |         JavaVersion javaTargetVersion = effectiveTargetVersion;
102 |         Element properties = doc.createElement("properties");
103 |         if (!convertToUtf8) {
104 |             properties.appendChild(doc.createComment(Messages.get("pom.sourceEncodingNotice")));
105 |         }
106 |         addTextElement(doc, properties, "project.build.sourceEncoding", "UTF-8");
107 |         addTextElement(doc, properties, "maven.compiler.source", javaSourceVersion.toString());
108 |         addTextElement(doc, properties, "maven.compiler.target", javaTargetVersion.toString());
109 |         project.appendChild(properties);
110 | 
111 |         // <dependencies>
112 |         boolean hasDependencies = !dependencies.isEmpty() || eclipseProject.webProject();
113 |         // libs/compile に JAR があるか（system スコープかつ exported=true）を判定
114 |         boolean hasCompileLibs = dependencies.stream()
115 |                 .anyMatch(d -> "system".equals(d.scope()) && d.exported());
116 |         if (hasDependencies) {
117 |             Element deps = doc.createElement("dependencies");
118 |             for (MavenDependency dep : dependencies) {
119 |                 Element dependency = doc.createElement("dependency");
120 |                 addTextElement(doc, dependency, "groupId", dep.groupId());
121 |                 addTextElement(doc, dependency, "artifactId", dep.artifactId());
122 |                 addTextElement(doc, dependency, "version", dep.version());
123 |                 if (dep.scope() != null && !dep.scope().isEmpty()) {
124 |                     addTextElement(doc, dependency, "scope", dep.scope());
125 |                 }
126 |                 if (dep.systemPath() != null) {
127 |                     // system スコープの JAR は libs/compile または libs/provided にコピーされる
128 |                     String fileName = Path.of(dep.systemPath()).getFileName().toString();
129 |                     String subDir = dep.exported() ? "libs/compile" : "libs/provided";
130 |                     addTextElement(doc, dependency, "systemPath",
131 |                             "${project.basedir}/" + subDir + "/" + fileName);
132 |                 }
133 |                 deps.appendChild(dependency);
134 |             }
135 |             // webProject の場合は Java EE / Jakarta EE API を provided で追加
136 |             if (eclipseProject.webProject() && eclipseProject.webVersion() != null) {
137 |                 String webVersion = eclipseProject.webVersion();
138 |                 boolean tooOld = webVersion.startsWith("2");
139 |                 String resolvedVersion = tooOld ? "3.0" : webVersion;
140 |                 JavaEEVersion javaEE = JavaEEVersion.fromWebVersion(resolvedVersion);
141 |                 Element dependency = doc.createElement("dependency");
142 |                 if (tooOld) {
143 |                     log.debug("  Web APIのバージョン {} は古すぎるため、3.0に置き換えて依存関係を追加", webVersion);
144 |                     deps.appendChild(doc.createComment(
145 |                             Messages.get("pom.legacyServletWarning", webVersion)));
146 |                 }
147 |                 addTextElement(doc, dependency, "groupId", javaEE.getGroupId());
148 |                 addTextElement(doc, dependency, "artifactId", javaEE.getArtifactId());
149 |                 addTextElement(doc, dependency, "version", javaEE.getVersion());
150 |                 addTextElement(doc, dependency, "scope", "provided");
151 |                 deps.appendChild(dependency);
152 |             }
153 |             project.appendChild(deps);
154 |         }
155 | 
156 |         // <build><plugins><plugin> maven-compiler-plugin
157 |         Element build = doc.createElement("build");
158 |         addTextElement(doc, build, "finalName", artifactId);
159 |         Element plugins = doc.createElement("plugins");
160 |         Element compilerPlugin = doc.createElement("plugin");
161 |         addTextElement(doc, compilerPlugin, "groupId", "org.apache.maven.plugins");
162 |         addTextElement(doc, compilerPlugin, "artifactId", "maven-compiler-plugin");
163 |         addTextElement(doc, compilerPlugin, "version", MAVEN_COMPILER_PLUGIN_VERSION);
164 |         plugins.appendChild(compilerPlugin);
165 |         // webProject の場合は maven-war-plugin を追加
166 |         if (eclipseProject.webProject()) {
167 |             Element warPlugin = doc.createElement("plugin");
168 |             addTextElement(doc, warPlugin, "groupId", "org.apache.maven.plugins");
169 |             addTextElement(doc, warPlugin, "artifactId", "maven-war-plugin");
170 |             addTextElement(doc, warPlugin, "version", MAVEN_WAR_PLUGIN_VERSION);
171 |             Element configuration = doc.createElement("configuration");
172 |             addTextElement(doc, configuration, "failOnMissingWebXml", "false");
173 |             // libs/compile に JAR がある場合は WEB-INF/lib へコピーする webResources 設定を追加
174 |             if (hasCompileLibs) {
175 |                 log.debug("  ${project.basedir}/libs/compile以下のJARファイルをコピーするようmaven-war-pluginを構成");
176 |                 Element webResources = doc.createElement("webResources");
177 |                 Element resource = doc.createElement("resource");
178 |                 addTextElement(doc, resource, "directory", "${project.basedir}/libs/compile");
179 |                 addTextElement(doc, resource, "targetPath", "WEB-INF/lib");
180 |                 Element includes = doc.createElement("includes");
181 |                 addTextElement(doc, includes, "include", "*.jar");
182 |                 resource.appendChild(includes);
183 |                 webResources.appendChild(resource);
184 |                 configuration.appendChild(webResources);
185 |             }
186 |             warPlugin.appendChild(configuration);
187 |             plugins.appendChild(warPlugin);
188 |         }
189 |         // --convert-to-utf8 かつ javaTargetVersion <= 8 の場合は native2ascii-maven-plugin を追加
190 |         // javaTargetVersion は 93-96 行で確定済み（javaTargetOverride 優先）
191 |         if (convertToUtf8 && !javaTargetVersion.isUnknown()
192 |                 && javaTargetVersion.compareTo(JavaVersion.Java8) <= 0) {
193 |             Element n2aPlugin = doc.createElement("plugin");
194 |             addTextElement(doc, n2aPlugin, "groupId", "org.codehaus.mojo");
195 |             addTextElement(doc, n2aPlugin, "artifactId", "native2ascii-maven-plugin");
196 |             addTextElement(doc, n2aPlugin, "version", NATIVE2ASCII_PLUGIN_VERSION);
197 |             Element executions = doc.createElement("executions");
198 |             Element execution = doc.createElement("execution");
199 |             addTextElement(doc, execution, "id", "native2ascii-utf8-resources");
200 |             addTextElement(doc, execution, "phase", "process-resources");
201 |             Element goals = doc.createElement("goals");
202 |             addTextElement(doc, goals, "goal", "resources");
203 |             execution.appendChild(goals);
204 |             Element configuration = doc.createElement("configuration");
205 |             addTextElement(doc, configuration, "encoding", "UTF-8");
206 |             addTextElement(doc, configuration, "srcDir", "${project.basedir}/src/main/resources-utf8");
207 |             addTextElement(doc, configuration, "outputDir", "${project.build.outputDirectory}");
208 |             execution.appendChild(configuration);
209 |             executions.appendChild(execution);
210 |             n2aPlugin.appendChild(executions);
211 |             plugins.appendChild(n2aPlugin);
212 |         }
213 |         build.appendChild(plugins);
214 |         project.appendChild(build);
215 | 
216 |         // XMLをファイルに書き出す
217 |         Files.createDirectories(outputDir);
218 |         TransformerFactory tf = TransformerFactory.newInstance();
219 |         Transformer transformer = tf.newTransformer();
220 |         transformer.setOutputProperty(OutputKeys.INDENT, "yes");
221 |         transformer.setOutputProperty(OutputKeys.ENCODING, "UTF-8");
222 |         transformer.setOutputProperty("{http://xml.apache.org/xslt}indent-amount", "2");
223 | 
224 |         Path pomPath = outputDir.resolve("pom.xml");
225 |         transformer.transform(new DOMSource(doc), new StreamResult(pomPath.toFile()));
226 | 
227 |         log.info(Messages.get("pom.generated", pomPath));
228 |     }
229 | 
230 |     private static void addTextElement(Document doc, Element parent, String tagName, String text) {
231 |         Element el = doc.createElement(tagName);
232 |         el.appendChild(doc.createTextNode(text));
233 |         parent.appendChild(el);
234 |     }
235 | }
