    private static final Logger log = AppLogger.get(LibertyServerXmlGenerator.class);

    /** server.xml 雛形。LIBERTY_FEATURE と ARTIFACT_ID をプレースホルダーとして使用する。 */
    private static final String SERVER_XML_TEMPLATE =
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" +
            "<server description=\"Liberty Server\">\n" +
