        }
    }

    @Test
    void javaProject_liberty_noLibertyMavenPlugin() throws Exception {
        // noLiberty=false でも Java プロジェクトには liberty-maven-plugin は出力されない
        PomGenerator.generate(javaProject(), List.of(), "com.example", "myapp", "1.0",
